namespace Companion.Api.Services;

/// <summary>
/// Finds the end-user handbook PDFs (German and English, generated by scripts/build-konzept.ps1 and committed in
/// docs/handbuch/&lt;lang&gt;/). In Development they are read straight from the repository, so a freshly generated PDF is served at once;
/// the Docker image (and any published build) keeps the same layout below the application folder (/app/docs/handbuch/&lt;lang&gt;/).
/// The handbook is delivered three ways: the endpoint GET /api/docs/handbook, the bridge download ZIP and the bridge tray menu.
/// </summary>
public sealed class HandbookFiles
{
    /// <summary>File names inside the bridge ZIP (next to the exe). The bridge looks for exactly these names (Handbook.cs there).</summary>
    public const string GermanZipName = "Handbuch (Deutsch).pdf";
    public const string EnglishZipName = "Handbook (English).pdf";

    public static readonly string[] Languages = ["de", "en"];

    public sealed record Handbook(string Language, string Path, string FileName, string ZipEntryName);

    private readonly string[] _roots;

    public HandbookFiles(IWebHostEnvironment environment)
    {
        // Development: the repository root is two levels above src/Companion.Api (same convention as BridgeBundle and AppVersion)
        var repository = Path.GetFullPath(Path.Combine(environment.ContentRootPath, "..", ".."));
        _roots = environment.IsDevelopment() ? [repository, AppContext.BaseDirectory] : [AppContext.BaseDirectory];
    }

    /// <summary>"de" (also empty and "de-AT" and the like) or "en" for everything else.</summary>
    public static string NormalizeLanguage(string? language)
    {
        var value = language?.Trim();
        if (string.IsNullOrEmpty(value) ||
            value.Equals("de", StringComparison.OrdinalIgnoreCase) ||
            value.StartsWith("de-", StringComparison.OrdinalIgnoreCase))
        {
            return "de";
        }
        return "en";
    }

    /// <summary>The handbook in this language ("de" or "en"), or null when no PDF is there.</summary>
    public Handbook? Find(string language)
    {
        var normalized = NormalizeLanguage(language);
        foreach (var root in _roots)
        {
            var directory = Path.Combine(root, "docs", "handbuch", normalized);
            if (!Directory.Exists(directory))
            {
                continue;
            }

            var pdf = Directory.EnumerateFiles(directory, "*.pdf").Order(StringComparer.OrdinalIgnoreCase).FirstOrDefault();
            if (pdf is not null)
            {
                return new Handbook(
                    normalized,
                    pdf,
                    Path.GetFileName(pdf),
                    normalized == "de" ? GermanZipName : EnglishZipName);
            }
        }
        return null;
    }

    /// <summary>Every handbook that is available (German first).</summary>
    public IEnumerable<Handbook> FindAll() => Languages.Select(Find).OfType<Handbook>();
}
